.pill,
article .pill {
    //Include atricle to override gereic a tag styles
    display: inline-flex;
    justify-content: space-around;
    align-items: center;
    gap: $measure--half;
    min-width: 90px;

    line-height: 1;
    font-size: $font-size--icon;
    border-radius: $border-radius-round;

    padding: calc(#{$measure--half} - 1px) $measure--threequarters
        $measure--half; // Adjust top padding to visually centre the text, accounting for font metrics.

    & + .pill {
        margin-left: $measure--half;
    }

    // Default appearance, including visited and keyboard focus states.
    &,
    &:link,
    &:visited,
    &:focus,
    &:active {
        color: $color-nearblack;
        background: transparent;
        border: solid $border-width-hairline $color-nearblack;
        text-decoration: none;
    }

    // Hover and active styles
    &:hover,
    &--active,
    &--active:link,
    &--active:visited,
    &--active:focus,
    &--active:active,
    &--active:hover {
        color: $color-purewhite;
        background: $color-red50;
        border-color: $color-red50;
        text-decoration: none;
    }

    &--active::after {
        font: var(--fa-font-regular);
        content: fa-content($fa-var-check);
    }
}
